class ExperimentSearchSetDimension(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    parameter_key: str
    value_type: Literal["INTEGER", "DECIMAL", "STRING", "BOOLEAN"]
    kind: Literal["SET"]
    values: list[str] = Field(
        ..., min_length=1, json_schema_extra={"uniqueItems": True}
    )
    minimum: None
    maximum: None
    step: None

    @model_validator(mode="after")
    def validate_typed_values(self):
        if len(set(self.values)) != len(self.values):
            raise ValueError("SET values must be unique")
        if self.value_type == "INTEGER":
            try:
                values = [Decimal(value) for value in self.values]
            except InvalidOperation as error:
                raise ValueError(
                    "INTEGER set values must be numeric integers"
                ) from error
            if any(value != value.to_integral_value() for value in values):
                raise ValueError("INTEGER set values must be integral")
        return self


class ExperimentSearchRangeDimension(BaseModel):
    """
    Numeric range bounds use canonical decimal strings. Runtime validation additionally enforces minimum < maximum, positive step, and integral values for INTEGER.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    parameter_key: str
    value_type: Literal["INTEGER", "DECIMAL"]
    kind: Literal["RANGE"]
    values: list = Field(..., max_length=0)
    minimum: str = Field(..., pattern="^-?(0|[1-9][0-9]*)(\\.[0-9]+)?$")
    maximum: str = Field(..., pattern="^-?(0|[1-9][0-9]*)(\\.[0-9]+)?$")
    step: str = Field(..., pattern="^(0\\.[0-9]*[1-9][0-9]*|[1-9][0-9]*(\\.[0-9]+)?)$")

    @model_validator(mode="after")
    def validate_ordered_range(self):
        try:
            minimum = Decimal(self.minimum)
            maximum = Decimal(self.maximum)
            step = Decimal(self.step)
        except InvalidOperation as error:
            raise ValueError("range bounds must be finite decimals") from error
        if minimum >= maximum:
            raise ValueError("minimum must be less than maximum")
        if step <= 0:
            raise ValueError("step must be positive")
        if self.value_type == "INTEGER" and any(
            value != value.to_integral_value() for value in (minimum, maximum, step)
        ):
            raise ValueError("INTEGER ranges require integral bounds and step")
        return self


