class AgentConfigUpdate(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        json_schema_extra={"minProperties": 1},
    )
    enabled: bool = cast(bool, None)
    runtime_profile: str = Field(default=cast(str, None), max_length=32, min_length=1)
    tool_timeout_seconds: int = Field(default=cast(int, None), ge=1)
    max_steps_override: int | None = Field(default=None, ge=1)
    max_tool_calls_override: int | None = Field(default=None, ge=1)

    @model_validator(mode="after")
    def require_at_least_one_update(self):
        if not self.model_fields_set:
            raise ValueError("at least one config update is required")
        return self


class AgentConfig(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    role_key: Literal[
        "RESEARCH_DIRECTOR",
        "FACTOR_SCIENTIST",
        "STRATEGY_SCIENTIST",
        "PORTFOLIO_ANALYST",
        "RED_TEAM_RESEARCHER",
        "PERFORMANCE_ANALYST",
    ]
    enabled: bool
    model_provider: str
    """
    Installation-level Remote Codex provider projection; not writable per role.
    """
    model_name: str
    """
    Installation-level Remote Codex model projection; not writable per role.
    """
    ai_connection_id: str
    ai_connection_revision: int = Field(..., ge=1)
    runtime_profile: str
    tool_timeout_seconds: int = Field(..., ge=1)
    max_steps_override: int | None = Field(..., ge=1)
    max_tool_calls_override: int | None = Field(..., ge=1)
    revision: int = Field(..., ge=1)
    action_capabilities: list[ActionCapability]
    created_at: AwareDatetime
    updated_at: AwareDatetime


class AgentConfigList(RootModel[list[AgentConfig]]):
    root: list[AgentConfig]


